    return {
      name: el.select('a').eq(0).text(),
      author: el.select('td').eq(2).text(),
      kind: el.select('td').eq(5).text(),
      wordCount: el.select('td').eq(3).text(),
      latest: el.select('a').eq(1).text() + ' ' + String(el.select('td').eq(4).text()).replace(/\d+-(\d+-\d+).*/, '$1').replace(new RegExp('(·s*)?([^\\d-])?(\\d{2})?' +String(new Date().getFullYear()).slice(-2) +'-'),'$1$2'),
      url: url,
    };
  });
</js>

exploreUrl:
@js:
var sort=[];
var push=(title,url,size)=>sort.push({
  	"title": title,
  	"url": url,
  	"style": {
   "layout_flexGrow": 1,
   "layout_flexBasisPercent": size
   }
 });

var url=source.key;
var fl=url+"/sort-1-1/";
var ph=url+"/top.html";
var qb=url+"/quanben.html";
var html=java.ajax(fl);
var src=java.ajax(ph);
var qbl=java.ajax(qb);

if(html&&src){
a=org.jsoup.Jsoup.parse(html).select(".sortChannel_nav a");
b=org.jsoup.Jsoup.parse(src).select(".content a");
c=org.jsoup.Jsoup.parse(qbl).select(".sortChannel_nav a");

push("🌹分类🌹",null,1)
    for(i in a){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
  url=String(url).replace("1.html","{{page}}.html").replace("1/","{{page}}/")
        push(title,url,size)
    };

push("🌹排行🌹",null,1)
    for(i in b){
        title=b[i].text()
        url=b[i].attr("href")
  url=String(url).replace(".htm","<,_{{page}}>.htm")
        size=0.25;
        push(title,url,size)
    }


 push("🌹全本🌹","/full-{{page}}/",1)
    for(i in c){
        title=c[i].text()
        url=c[i].attr("href")
  url=String(url).replace(".htm","<,_{{page}}>.htm")
        size=0.25;
        push(title,url,size)
    }

}else{
  java.toast("发现列表获取失败！")
}

JSON.stringify(sort)

